import backtrader as bt
import math


class Trading0DTEOpeningRangeStrategy(bt.Strategy):
    def __init__(self):
        self.rsi = bt.indicators.RSI(self.data.close, period=14)
        self.order = None
        self.stop_order = None
        self.session_date = None
        self.range_high = None
        self.range_low = None

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return

        if order.status == order.Completed:
            if order is self.order:
                self.order = None
                if self.position:
                    if self.position.size > 0:
                        stop_price = self.range_low - 0.01
                        self.stop_order = self.sell(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=stop_price,
                        )
                    else:
                        stop_price = self.range_high + 0.01
                        self.stop_order = self.buy(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=stop_price,
                        )
            elif order is self.stop_order:
                self.stop_order = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            if order is self.order:
                self.order = None
            if order is self.stop_order:
                self.stop_order = None

    def _exit_position(self):
        if self.stop_order is not None:
            self.cancel(self.stop_order)
        self.order = self.close()

    def next(self):
        dt = self.data.datetime.datetime(0)
        current_date = dt.date()
        minutes = dt.hour * 60 + dt.minute

        if current_date != self.session_date:
            self.session_date = current_date
            self.range_high = None
            self.range_low = None

        if 570 <= minutes <= 610:
            high = self.data.high[0]
            low = self.data.low[0]
            self.range_high = high if self.range_high is None else max(self.range_high, high)
            self.range_low = low if self.range_low is None else min(self.range_low, low)
            return

        if self.order is not None:
            return

        if self.position:
            if minutes >= 950:
                self._exit_position()
            elif self.position.size > 0:
                if self.range_low <= self.data.close[0] <= self.range_high:
                    self._exit_position()
            elif self.range_low <= self.data.close[0] <= self.range_high:
                self._exit_position()
            return

        if self.stop_order is not None or minutes <= 610 or minutes >= 950:
            return
        if self.range_high is None or self.range_low is None:
            return

        close = self.data.close[0]
        rsi = self.rsi[0]
        increasing_volume = self.data.volume[0] > self.data.volume[-1]

        if close > self.range_high and rsi <= 70:
            confirmed = increasing_volume or rsi > 50
            stop_price = self.range_low - 0.01
            risk_per_share = close - stop_price
            size = math.floor((self.broker.getvalue() * 0.01) / risk_per_share)
            if confirmed and size > 0:
                self.order = self.buy(size=size)
        elif close < self.range_low and rsi >= 30:
            confirmed = increasing_volume or rsi < 50
            stop_price = self.range_high + 0.01
            risk_per_share = stop_price - close
            size = math.floor((self.broker.getvalue() * 0.01) / risk_per_share)
            if confirmed and size > 0:
                self.order = self.sell(size=size)
